/** Synthetic lexical-retrieval cases; no deployed persona or chat history. */
export interface MemoryEvaluationCase {id:string;question:string;query:string;expectedFacts:string[];evidenceIds:string[];category:string;expectedBehavior:'answer'|'uncertain'|'not-found'}
